package main

import (
	"fmt"
	"time"
)

func producer(jobs chan<- int, n int) {
	for i := 1; i <= n; i++ {
		fmt.Println("producing job", i)
		jobs <- i
	}
	close(jobs)
}

func consumer(jobs <-chan int) {
	for job := range jobs {
		time.Sleep(50 * time.Millisecond)
		fmt.Println("consumed job", job)
	}
}

func main() {
	// TODO: create a buffered channel with capacity 3
	jobs := make(chan int)

	go producer(jobs, 5)
	consumer(jobs)

	fmt.Println("all jobs done")
}
